from lib import *
S = SS('f127')
R = J('f127')
steps = [
    step("默认情况下,request.host 与 url_for(_external=True) 直接取自请求里的 Host 头:Host 是 example.com、other.test、example.com:8080 时,生成的绝对地址分别是 http://example.com/info、http://other.test/info、http://example.com:8080/info,三个都是 200。任何 Host 都被接受。所以在邮件、密码重置链接里直接用这类地址,地址就是由请求方决定的。", t=tl(S(1)), done=lidx(S(1), 'Host: example.com', 'Host: other.test', 'Host: example.com:8080'), mark=lidx(S(1), '任何 Host'), kv=KV([['request.host', '取自 Host 头'], ['url_for(_external=True)', '同样取自 Host 头']], ['url_for(_external=True)'])),
    step("TRUSTED_HOSTS(Flask 3.1)只接受名单里的 Host(这里是 ['example.com', '.example.org']):example.com 与 example.com:8080 → 200(端口不影响匹配);www.example.org 与 example.org → 200(前面带点表示该域名及其所有子域名);other.test、evil-example.com、空 Host → 400;写成大写的 EXAMPLE.com 也是 400——这次实验里匹配区分大小写,而 Host 名按规范不区分大小写,浏览器通常发小写,这一点我没有进一步查原因。", t=tl(S(2)), done=lidx(S(2), "'example.com'", "'www.example.org'", "'example.org'"), mark=lidx(S(2), 'EXAMPLE.com', 'other.test', 'evil-example.com', "''"), kv=KV([['名单里的 Host', '200,端口忽略'], ['.example.org', '该域及全部子域'], ['不在名单', '400']], ['不在名单'])),
    step("SERVER_NAME:设成 example.com 后,请求 Host 是 other.test 时仍是 200,request.host 还是 other.test(没有拒绝),但 url_for(_external=True) 生成的是 http://example.com/info——外部地址固定用配置的域名;请求之外(应用上下文里)的 url_for(_external=True) 也是 http://example.com/info。所以 SERVER_NAME 能让外部链接不再随 Host 变化,但不能拒绝坏的 Host(那要靠 TRUSTED_HOSTS)。", t=tl(S(3)), done=lidx(S(3), 'Host: example.com', '请求之外'), mark=lidx(S(3), 'other.test'), kv=KV([['SERVER_NAME', '固定外部链接的域名,不拒绝请求'], ['TRUSTED_HOSTS', '拒绝不在名单里的 Host']], ['SERVER_NAME'])),
    step("最稳妥的做法是不依赖 Host 生成邮件里的绝对链接:用配置里的固定基地址拼接。请求 Host 是 other.test 时,基于配置的链接是 https://app.example.com/info,而基于 Host 的 url_for(_external=True) 是 http://other.test/info。", t=tl(S(4)), done=lidx(S(4), 'Host: other.test'), kv=KV([['固定基地址', '不受请求影响'], ['url_for(_external=True)', '随 Host 变']], ['固定基地址'])),
    step("反向代理后面:没有 ProxyFix 时,带着 X-Forwarded-Host: public.example.com 的请求,request.host 仍是 internal:8000(这个头被忽略);用了 ProxyFix(x_host=1) 后,request.host 变成 public.example.com,外部链接也随之变化。只有前面确实有会覆盖这个头的可信代理时才启用,否则客户端自己就能设置它。(见第 135 篇)", t=tl(S(5)), mark=lidx(S(5), 'ProxyFix(x_host=1)'), done=lidx(S(5), '没有 ProxyFix'), kv=KV([['没有 ProxyFix', '忽略 X-Forwarded-Host'], ['ProxyFix(x_host=1)', '信任它,必须有可信代理']], ['ProxyFix(x_host=1)'])),
    step("真实 gunicorn 上的结果与 test client 一致:TRUSTED_HOSTS = ['example.com'] 时,Host: example.com → 200;Host: other.test → 400;Host 写成 127.0.0.1:端口(不在名单里)也是 400——这意味着本机健康检查如果用 IP 访问,要把它加进名单或让检查带上正确的 Host。", t=tl(S(6)), done=lidx(S(6), 'Host: example.com'), mark=lidx(S(6), 'other.test', '127.0.0.1'), kv=KV([['不在名单的 Host', '400'], ['健康检查', '用 IP 访问也会被拒']], ['健康检查'])),
]
